def compute(vars):
    value = vars["v2"] - vars["v1"]
    return {
        "value": value,
        "trace": {
            "accelerated_depreciation_2018": vars["v1"],
            "accelerated_depreciation_2019": vars["v2"],
            "difference_2019_minus_2018": value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
